        type: type || "",
        buyerEmail: buyer || "",
        sellerEmail: seller || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
        status: status
      }).toString();
      // console.log('queryParams', queryParams)
      let params = {
        url: `user-TradeHistory?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      // console.log('response', response)
      if (response.status) {

        setTradeData(response.getTradeHistoryTblDetails);
        setLoading(false);
        setTotalPages(response.totalItems);
